import re, pathlib
root = pathlib.Path('/workspace/submission/src/de/rub/nds')

# --- 1. Parser base: add a bounds-checked byte array parse, fix off-by-one ---
p = root/'tlsattacker/core/layer/data/Parser.java'
s = p.read_text()
s = s.replace("""    protected byte[] parseArrayOrTillEnd(int n) {
        if (n >= 0 && n < getBytesLeft()) {""","""    protected byte[] parseArrayOrTillEnd(int n) {
        if (n >= 0 && n <= getBytesLeft()) {""")
anchor = """    protected byte[] parseTillEnd() {
        return parseByteArrayField(getBytesLeft());
    }"""
assert anchor in s
s = s.replace(anchor, anchor + """

    /**
     * Offline repair: length fields are 62 bit varints, so the requested amount has to be validated
     * against the remaining input before an array is allocated. A too large (or negative) length is
     * a truncated encoding and reported as end of stream.
     *
     * @param length Number of bytes claimed by a preceding length field
     * @return The parsed bytes
     */
    protected byte[] parseByteArrayFieldChecked(long length) {
        if (length < 0 || length > (long) getBytesLeft()) {
            throw new EndOfStreamException("Claimed length " + length + " exceeds remaining bytes");
        }
        return parseByteArrayField((int) length);
    }""")
p.write_text(s)

# --- 2. QuicFrameParser: frame type must not be narrowed to a byte ---
p = root/'tlsattacker/core/quic/parser/frame/QuicFrameParser.java'
s = p.read_text()
s = s.replace("frame.setFrameType((byte) parseVariableLengthInteger());","frame.setFrameType(parseVariableLengthInteger());")
p.write_text(s)

# --- 3. frame DTOs: widen ModifiableInteger fields to ModifiableLong ---
dto = ['StreamFrame','ResetStreamFrame','StopSendingFrame','MaxDataFrame','MaxStreamDataFrame',
       'MaxStreamsFrame','DataBlockedFrame','StreamDataBlockedFrame','StreamsBlockedFrame',
       'RetireConnectionIdFrame','DatagramFrame']
for name in dto:
    p = root/('tlsattacker/core/quic/frame/%s.java' % name)
    s = p.read_text()
    if 'ModifiableInteger' not in s:
        continue
    has_long = 'ModifiableLong' in s
    s = s.replace('import de.rub.nds.modifiablevariable.integer.ModifiableInteger;\n',
                  '' if has_long else 'import de.rub.nds.modifiablevariable.longint.ModifiableLong;\n')
    s = s.replace('ModifiableInteger', 'ModifiableLong')
    # widen the setter parameters that feed safelySetValue
    def fix(m):
        return m.group(0).replace('(%s ' % m.group(1), '(long ', 1)
    s = re.sub(r'public void (set\w+)\(int (\w+)\) \{\n(\s+)(this\.\w+ =\s*\n?\s*ModifiableVariableFactory\.safelySetValue\([^;]*?\);)',
               lambda m: m.group(0).replace('(int ', '(long ', 1), s)
    p.write_text(s)
print('dto done')
PYEOF
